<h3>Weiterlesen</h3>
<p><a href="/community/guide-placeholder/index" rel="ugc nofollow noopener">OutBrick-Spielanleitungen</a></p>
<ul><li><a href="/community/guide-placeholder/specials-and-stars" rel="ugc nofollow noopener">Spezialsteine, Ziele und Punktesterne</a></li><li><a href="/community/guide-placeholder/journey" rel="ugc nofollow noopener">Orientierung auf der Reise</a></li><li><a href="/community/guide-placeholder/voiceover" rel="ugc nofollow noopener">Spielen mit VoiceOver</a></li><li><a href="/community/guide-placeholder/settings" rel="ugc nofollow noopener">Bedienungshilfen und angenehme Einstellungen</a></li><li><a href="/community/guide-placeholder/lives-moves-undos" rel="ugc nofollow noopener">Leben, Züge, Rückgängig und freiwillige Videos</a></li><li><a href="/community/guide-placeholder/asking-for-help" rel="ugc nofollow noopener">Hilfe und Probleme mit Bedienungshilfen melden</a></li><li><a href="/community/guide-placeholder/versions" rel="ugc nofollow noopener">Welche Spielversion spiele ich?</a></li></ul>';
BEGIN
 SELECT thread_id INTO tid FROM player_guides WHERE locale = 'de' AND key = 'first-board';
 IF tid IS NULL THEN RETURN; END IF;
 FOR target IN SELECT g.key, t.id, t.slug FROM player_guides g JOIN threads t ON t.id = g.thread_id WHERE g.locale = 'de' LOOP
  old_md := replace(old_md, '/community/guide-placeholder/' || target.key, '/de/community/t/' || target.id || '/' || target.slug);
  new_md := replace(new_md, '/community/guide-placeholder/' || target.key, '/de/community/t/' || target.id || '/' || target.slug);
  new_html := replace(new_html, '/community/guide-placeholder/' || target.key, '/de/community/t/' || target.id || '/' || target.slug);
 END LOOP;
 UPDATE posts SET body_md = new_md, body_html = new_html WHERE thread_id = tid AND number = 1 AND body_md = old_md;
END $guide$;

